/* Everyday conversation library; all examples are composed for HaloChina. */
(() => {
 'use strict';
 const T=window.HALO_DAILY,P=T.flatMap(t=>t.phrases),groups=[...new Set(T.map(t=>t.group))];
 let app,route={},query='',group='',savedOnly=false,limit=24,hidePinyin=false,hideMeaning=false,generation=0,dialogueTopic=null,pauseTimer=null;
 const $=s=>document.querySelector(s),E=x=>app.C.escape(x),link=id=>`#/daily-topic/1/${id}`;
 const progress=()=>app.progress.daily||(app.progress.daily={saved:[],practiced:[]});
 const button=(text,action,extra='',classes='')=>`<button class="button ${classes}" data-daily-action="${action}" ${extra}>${text}</button>`;
 function match(p){const text=app.C.normalize(`${p.zh} ${p.pinyin} ${p.vi}`),key=app.C.normalize(query).trim();return text.includes(key)||text.replace(/\s/g,'').includes(key.replace(/\s/g,''));}
 function selectedTopics(){const key=app.C.normalize(query).trim();return T.filter(t=>(!group||t.group===group)&&(!key||app.C.normalize(`${t.title} ${t.description}`).includes(key)||t.phrases.some(match)));}
 function selectedPhrases(){return P.filter(p=>(!group||T.find(t=>t.id===p.topicId).group===group)&&(!savedOnly||progress().saved.includes(p.id))&&(!query.trim()||match(p)));}
 function topicCard(t){const done=t.phrases.filter(p=>progress().practiced.includes(p.id)).length;return `<a class="daily-topic-card daily-tone-${t.number%4}" href="${link(t.id)}"><div class="daily-topic-top"><span class="daily-topic-icon">${t.icon}</span><span class="daily-category">${E(t.group)}</span></div><h2>${E(t.title)}</h2><p>${E(t.description)}</p><div class="daily-card-meta"><span>10 câu mẫu · 1 hội thoại</span><b>↗</b></div><div class="progress-track"><i style="width:${done/10*100}%"></i></div><span class="daily-topic-progress">${done?`${done}/10 câu đã luyện`:'Sẵn sàng bắt đầu'}</span></a>`;}
 function phraseCard(p,origin=false){const topic=T.find(t=>t.id===p.topicId),saved=progress().saved.includes(p.id),practiced=progress().practiced.includes(p.id);return `<article class="daily-phrase ${practiced?'is-practiced':''}" data-phrase-id="${p.id}"><div class="daily-phrase-head">${origin?`<a href="${link(topic.id)}" class="daily-origin">${topic.icon} ${E(topic.title)} ↗</a>`:`<span class="daily-phrase-number">CÂU ${String(p.number).padStart(2,'0')}</span>`}<button class="daily-save ${saved?'is-saved':''}" data-daily-action="save" data-id="${p.id}" aria-label="${saved?'Bỏ lưu':'Lưu'} câu ${p.number}" aria-pressed="${saved}">${saved?'♥':'♡'} <span>${saved?'Đã lưu':'Lưu câu'}</span></button></div><p class="daily-zh" lang="zh">${E(p.zh)}</p><p class="daily-pinyin" lang="zh-Latn">${E(p.pinyin)}</p><p class="daily-meaning">${E(p.vi)}</p><div class="daily-phrase-actions">${button(app.icon('sound')+' Nghe','speak',`data-id="${p.id}"`,'ghost small')}${button('Nghe chậm','slow',`data-id="${p.id}"`,'ghost small')}${button(practiced?'✓ Đã luyện':'Đánh dấu đã luyện','practice',`data-id="${p.id}" aria-pressed="${practiced}"`,practiced?'small daily-practiced':'ghost small')}<button class="daily-copy" data-daily-action="copy" data-id="${p.id}">Sao chép</button></div></article>`;}
 function renderResults(){const topics=selectedTopics(),phrases=selectedPhrases();if(savedOnly)return `<div class="daily-result-count" role="status">${phrases.length} câu đã lưu phù hợp</div>${phrases.length?`<div class="daily-phrase-list ${hidePinyin?'hide-pinyin':''} ${hideMeaning?'hide-meaning':''}">${phrases.slice(0,limit).map(p=>phraseCard(p,true)).join('')}</div>${phrases.length>limit?button(`Xem thêm ${Math.min(24,phrases.length-limit)} câu`,'more','','ghost daily-more'):''}`:'<div class="empty"><h2>Chưa có câu đã lưu phù hợp</h2><p>Bấm ♡ cạnh câu bạn muốn nhớ để tạo bộ câu giao tiếp của riêng mình.</p>'+button('Xem tất cả chủ đề','show-all')+'</div>'}`;
  const search=query.trim();return `<div class="daily-result-count" role="status">${topics.length} chủ đề${search?` phù hợp · ${phrases.length} câu khớp tìm kiếm`:' · Chọn một tình huống để bắt đầu'}</div>${topics.length?`<div class="daily-topic-grid">${topics.map(topicCard).join('')}</div>`:!phrases.length?'<div class="empty"><h2>Chưa tìm thấy nội dung phù hợp</h2><p>Thử một từ khóa ngắn hơn, pinyin không dấu hoặc tên tình huống.</p></div>':''}${search&&phrases.length?`<div class="section-heading daily-match-heading"><h2>Câu giao tiếp phù hợp</h2><span class="subtle">${Math.min(limit,phrases.length)} / ${phrases.length} câu</span></div><div class="daily-phrase-list ${hidePinyin?'hide-pinyin':''} ${hideMeaning?'hide-meaning':''}">${phrases.slice(0,limit).map(p=>phraseCard(p,true)).join('')}</div>${phrases.length>limit?button('Xem thêm câu phù hợp','more','','ghost daily-more'):''}`:''}`;
 }
 function renderHome(r){route=r;return `<section class="daily-hero"><div><span class="pink-eyebrow">NGA ANH NÓI TIẾNG TRUNG MỖI NGÀY</span><h1>Một câu nhỏ,<br>mở ra <em>một cuộc trò chuyện.</em></h1><p>Học những câu có thể dùng trong đời sống: từ lời chào đầu tiên<br>đến gọi món, hỏi đường và trò chuyện cùng bạn bè.</p><span class="daily-authored">✿ Tự biên soạn · Chữ giản thể · Có pinyin & nghĩa Việt</span></div><div class="daily-hero-bubbles" aria-hidden="true"><span>你好呀！<small>Chào bạn nhé!</small></span><span>很高兴认识你 ♡<small>Rất vui được làm quen.</small></span><b>✿</b></div></section><div class="daily-stats"><div><strong>${T.length}</strong><span>Chủ đề hằng ngày</span></div><div><strong>${P.length}</strong><span>Câu giao tiếp mẫu</span></div><div><strong>${T.length}</strong><span>Hội thoại thực hành</span></div><div><strong class="daily-practice-count">${progress().practiced.length}</strong><span>Câu đã tự luyện</span></div></div><div class="daily-filters"><label class="search-wrap">${app.icon('search')}<input id="daily-search" class="search" type="search" value="${E(query)}" placeholder="Tìm chủ đề, chữ Hán, pinyin hoặc nghĩa Việt…" aria-label="Tìm câu giao tiếp"></label><label class="checkbox-label"><input id="daily-saved-only" type="checkbox" ${savedOnly?'checked':''}> Chỉ câu đã lưu (<span class="daily-saved-count">${progress().saved.length}</span>)</label></div><div class="daily-group-tabs" role="group" aria-label="Nhóm chủ đề">${['',...groups].map(g=>`<button data-daily-action="group" data-group="${E(g)}" aria-pressed="${g===group}" class="${g===group?'active':''}">${g?E(g):'Tất cả chủ đề'}</button>`).join('')}</div><div id="daily-results">${renderResults()}</div><div class="daily-about"><strong>Học theo 3 bước: nghe · nói theo · thử dùng trong tình huống.</strong><p>Câu mẫu và hội thoại do HaloChina tự biên soạn, có thể điều chỉnh tên và xưng hô theo ngữ cảnh. Nút nghe dùng giọng tổng hợp của thiết bị. Câu đã lưu và đã luyện nằm trên trình duyệt này, kèm trong bản sao tiến độ JSON.</p></div>`;}
 function renderTopic(r){route=r;const t=T.find(t=>t.id===r.id);if(!t)return '<div class="empty"><h1>Chưa có chủ đề này</h1><a class="button" href="#/communication/1">Về giao tiếp hằng ngày</a></div>';return `<div class="page-title daily-title"><a class="back-link" href="#/communication/1">← Giao tiếp hằng ngày</a><span class="daily-detail-category">${t.icon} ${E(t.group)}</span><h1>${E(t.title)}</h1><p>${E(t.description)} · 10 câu mẫu và 1 hội thoại, do HaloChina biên soạn.</p></div><div class="daily-study-toolbar"><div class="daily-toggle-group"><label class="checkbox-label"><input id="daily-hide-pinyin" type="checkbox" ${hidePinyin?'checked':''}> Ẩn pinyin</label><label class="checkbox-label"><input id="daily-hide-meaning" type="checkbox" ${hideMeaning?'checked':''}> Ẩn nghĩa để tự ôn</label></div><div class="actions-inline"><button class="button ghost small" data-daily-action="go-dialogue">Luyện hội thoại ↓</button>${button('↓ Xuất CSV','csv',`data-topic="${t.id}"`,'ghost small')}${button('In / lưu PDF','print','','ghost small')}</div></div><div class="daily-tip"><strong>Mẹo dùng tự nhiên</strong><p>${E(t.tip)}</p></div><div class="daily-content ${hidePinyin?'hide-pinyin':''} ${hideMeaning?'hide-meaning':''}"><section aria-label="Câu giao tiếp mẫu"><div class="section-heading"><h2>10 câu dùng trong tình huống này</h2><span class="daily-topic-done">${t.phrases.filter(p=>progress().practiced.includes(p.id)).length}/10 đã luyện</span></div><div class="daily-phrase-list" id="daily-topic-phrases">${t.phrases.map(p=>phraseCard(p)).join('')}</div></section><section class="daily-dialogue" id="daily-dialogue" aria-labelledby="daily-dialogue-title"><div class="section-heading"><div><span class="pink-eyebrow">THỬ ĐỔI VAI VỚI MỘT NGƯỜI BẠN</span><h2 id="daily-dialogue-title">Hội thoại thực hành</h2></div>${button(app.icon('sound')+' Nghe cả hội thoại','dialogue',`data-topic="${t.id}"`,'daily-dialogue-button')}</div><p class="daily-dialogue-help">Nghe lần đầu để hiểu ý, sau đó ẩn nghĩa và đọc theo từng vai. Có thể bấm nghe riêng một lượt nói.</p><p class="daily-play-status" role="status" aria-live="polite"></p><div class="daily-dialogue-lines">${t.dialogue.map((line,i)=>`<article class="daily-dialogue-line speaker-${line.speaker.toLowerCase()}" data-dialogue-index="${i}"><span class="dialogue-avatar">${line.speaker}</span><div class="dialogue-bubble"><div class="dialogue-speaker"><strong>${E(t.roles[line.speaker==='A'?0:1])}</strong><button class="icon-button" data-daily-action="dialogue-line" data-topic="${t.id}" data-line="${i}" aria-label="Nghe lượt nói ${i+1}">${app.icon('sound')}</button></div><p class="daily-zh" lang="zh">${E(line.zh)}</p><p class="daily-pinyin" lang="zh-Latn">${E(line.pinyin)}</p><p class="daily-meaning">${E(line.vi)}</p></div></article>`).join('')}</div></section></div><div class="daily-next-topics"><a class="button ghost" href="#/communication/1">← Chọn chủ đề khác</a><a class="button" href="${link(T[t.number%T.length].id)}">Chủ đề tiếp theo →</a></div>`;}
 function refreshResults(){if($('#daily-results'))$('#daily-results').innerHTML=renderResults();}
 function updateCounts(){document.querySelectorAll('.daily-saved-count').forEach(e=>e.textContent=progress().saved.length);document.querySelectorAll('.daily-practice-count').forEach(e=>e.textContent=progress().practiced.length);const t=T.find(t=>t.id===route.id);if(t&&$('.daily-topic-done'))$('.daily-topic-done').textContent=`${t.phrases.filter(p=>progress().practiced.includes(p.id)).length}/10 đã luyện`;}
 function updatePhrase(p){if(route.view==='communication'){refreshResults();updateCounts();return;}const old=$(`[data-phrase-id="${p.id}"]`);if(old){const wrapper=document.createElement('div');wrapper.innerHTML=phraseCard(p);old.replaceWith(wrapper.firstElementChild);}updateCounts();}
 function stopSpeech(){generation++;clearTimeout(pauseTimer);dialogueTopic=null;if('speechSynthesis'in window)window.speechSynthesis.cancel();window.HaloMusic?.cancelSpeech();document.querySelectorAll('.daily-dialogue-line.is-speaking').forEach(e=>e.classList.remove('is-speaking'));const b=$('.daily-dialogue-button');if(b){b.innerHTML=app.icon('sound')+' Nghe cả hội thoại';b.setAttribute('aria-pressed','false');}}
 function speakPhrase(p,slow=false){stopSpeech();app.speak(p.zh,{rate:slow ? .58 : .85});}
 function playDialogue(topic){if(dialogueTopic===topic.id){stopSpeech();if($('.daily-play-status'))$('.daily-play-status').textContent='Đã dừng hội thoại.';return;}stopSpeech();dialogueTopic=topic.id;const token=generation;let index=0;const button=$('.daily-dialogue-button');if(button){button.textContent='■ Dừng hội thoại';button.setAttribute('aria-pressed','true');}
  const step=()=>{if(token!==generation||route.view!=='daily-topic'||route.id!==topic.id)return;if(index===topic.dialogue.length){stopSpeech();if($('.daily-play-status'))$('.daily-play-status').textContent='✓ Đã nghe xong. Bây giờ Nga Anh thử đổi vai và đọc theo nhé.';return;}const line=topic.dialogue[index];document.querySelectorAll('.daily-dialogue-line').forEach((e,i)=>e.classList.toggle('is-speaking',i===index));if($('.daily-play-status'))$('.daily-play-status').textContent=`Đang nghe ${topic.roles[line.speaker==='A'?0:1]} · lượt ${index+1}/${topic.dialogue.length}`;
   const submitted=app.speak(line.zh,{rate:.78,onEnd:()=>{if(token===generation){index++;pauseTimer=setTimeout(step,380);}},onError:()=>{if(token===generation){stopSpeech();if($('.daily-play-status'))$('.daily-play-status').textContent='Chưa phát được âm thanh. Bạn có thể đọc theo pinyin hoặc thử lại khi thiết bị có giọng tiếng Trung.';}}});if(!submitted){stopSpeech();}
  };step();
 }
 function afterRender(r){const changed=route.view!==r.view||route.id!==r.id;if(changed||!['communication','daily-topic'].includes(r.view))stopSpeech();route=r;if(r.view==='progress'){const section=document.createElement('section');section.className='game-panel daily-progress-summary';section.innerHTML=`<div><span class="pink-eyebrow">GIAO TIẾP HẰNG NGÀY</span><h2>${progress().practiced.length}/${P.length} câu đã tự luyện</h2><p>${progress().saved.length} câu đã lưu · ${T.length} chủ đề để trò chuyện tự tin hơn</p></div><a class="button" href="#/communication/1">Mở góc giao tiếp →</a>`;$('#main').appendChild(section);}}
 function init(a){app=a;progress();document.addEventListener('click',async event=>{const b=event.target.closest('[data-daily-action]');if(!b)return;const action=b.dataset.dailyAction,p=P.find(p=>p.id===b.dataset.id);switch(action){
  case 'group':group=b.dataset.group;limit=24;document.querySelectorAll('.daily-group-tabs button').forEach(x=>{x.classList.toggle('active',x.dataset.group===group);x.setAttribute('aria-pressed',String(x.dataset.group===group));});refreshResults();break;
  case 'show-all':query='';group='';savedOnly=false;limit=24;app.render();break;
  case 'more':limit+=24;refreshResults();break;
  case 'save':if(p){const a=progress().saved,index=a.indexOf(p.id);if(index>=0)a.splice(index,1);else a.push(p.id);app.persist();updatePhrase(p);app.toast(index>=0?'Đã bỏ lưu câu giao tiếp.':'Đã lưu câu để Nga Anh ôn lại.');}break;
  case 'practice':if(p){const a=progress().practiced,index=a.indexOf(p.id);if(index>=0)a.splice(index,1);else a.push(p.id);app.persist();updatePhrase(p);app.toast(index>=0?'Đã bỏ đánh dấu luyện câu.':'Giỏi lắm! Đã ghi nhận Nga Anh tự luyện câu này.');}break;
  case 'speak':if(p)speakPhrase(p);break;
  case 'slow':if(p)speakPhrase(p,true);break;
  case 'copy':if(p)try{await navigator.clipboard.writeText(`${p.zh}\n${p.pinyin}\n${p.vi}`);app.toast('Đã sao chép câu, pinyin và nghĩa.');}catch{app.toast('Chưa sao chép được. Bạn có thể chọn phần chữ để sao chép thủ công.');}break;
  case 'dialogue':{const t=T.find(t=>t.id===b.dataset.topic);if(t)playDialogue(t);break;}
  case 'dialogue-line':{const t=T.find(t=>t.id===b.dataset.topic),line=t?.dialogue[Number(b.dataset.line)];if(line)speakPhrase(line);break;}
  case 'print':window.print();break;
  case 'go-dialogue':$('#daily-dialogue')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});break;
  case 'csv':{const t=T.find(t=>t.id===b.dataset.topic);if(t)app.download(`Nga-Anh-giao-tiep-${t.id}.csv`,app.C.csv([['Chủ đề','Tiếng Trung','Pinyin','Nghĩa tiếng Việt','Ghi nguồn'],...t.phrases.map(p=>[t.title,p.zh,p.pinyin,p.vi,'HaloChina — nội dung tự biên soạn'])]),'text/csv;charset=utf-8');break;}
 }});
  document.addEventListener('input',event=>{if(event.target.id==='daily-search'){query=event.target.value;limit=24;refreshResults();}});
  document.addEventListener('change',event=>{if(event.target.id==='daily-saved-only'){savedOnly=event.target.checked;limit=24;refreshResults();}if(event.target.id==='daily-hide-pinyin'){hidePinyin=event.target.checked;$('.daily-content')?.classList.toggle('hide-pinyin',hidePinyin);}if(event.target.id==='daily-hide-meaning'){hideMeaning=event.target.checked;$('.daily-content')?.classList.toggle('hide-meaning',hideMeaning);}});
  document.addEventListener('visibilitychange',()=>{if(document.hidden)stopSpeech();});window.addEventListener('pagehide',stopSpeech);window.addEventListener('hashchange',stopSpeech);
 }
 window.HaloDaily={init,renderHome,renderTopic,afterRender};
})();
